    slot: Option<Slot>,
}

impl WireBlock {
    fn plain(value: Value) -> Self {
        Self { value, slot: None }
    }

    fn kind(&self) -> &str {
        self.value["type"].as_str().unwrap_or("")
    }

    fn is_tool_use(&self) -> bool {
        self.kind() == "tool_use"
